const items = $input.all();
const state = $getWorkflowStaticData("node");
const previous = state.matchIds ?? [];
if (
  !Array.isArray(previous) ||
  previous.some((id) => typeof id !== "string") ||
  new Set(previous).size !== previous.length
)
  throw new Error("Invalid match history.");
const seen = new Set(previous),
  fresh = items.filter((item) => !seen.has(item.json.id));
if (seen.size + fresh.length > 10000)
  throw new Error("Match history is full; inspect and reset history before continuing.");
if (fresh.length) state.matchIds = [...previous, ...fresh.map((item) => item.json.id)];
return fresh;

const prepare = function prepareMatches({ body }) {
  if (!body || typeof body !== "object" || Array.isArray(body) || !Array.isArray(body.data)) {
    throw new Error("Live Tennis API must return an object with a data array.");
  }
  if (body.data.length > 50)
    throw new Error("The first match page exceeds the configured 50-item limit.");
  const hasMore = body.meta?.has_more ?? null;
  if (hasMore !== null && typeof hasMore !== "boolean")
    throw new Error("Invalid match pagination metadata.");
  const matches = [],
    ids = new Set();
  for (const match of body.data) {
    if (
      !match ||
      typeof match !== "object" ||
      Array.isArray(match) ||
      !Number.isSafeInteger(match.id) ||
      match.id < 1
    ) {
      throw new Error("Every match must have a positive integer ID.");
    }
    const p1 = match.players?.p1?.name,
      p2 = match.players?.p2?.name,
      status = match.status;
    if ([p1, p2, status].some((value) => typeof value !== "string" || !value.trim())) {
      throw new Error("Every match must have both player names and a status.");
    }
    const text = `🎾 New live match: ${p1} vs ${p2} — ${status}`;
    if (text.length > 2000)
      throw new Error("A match announcement exceeds Discord’s 2000-character limit.");
    const id = String(match.id);
    if (ids.has(id)) continue;
    ids.add(id);
    matches.push({ id, text });
  }
  return { matches, received: body.data.length, unique: matches.length, hasMore };
};

return prepare({ body: $input.first().json }).matches.map((match) => ({ json: match }));
